fun decodeBase64ToBitmap(base64String: String): Bitmap? {
    return try {
        // Clean the string if it contains data URI prefixes like "data:image/png;base64,"
        val cleanedString = base64String.substringAfter(",")
        val decodedBytes = Base64.decode(cleanedString, Base64.DEFAULT)
        BitmapFactory.decodeByteArray(decodedBytes, 0, decodedBytes.size)
    } catch (e: IllegalArgumentException) {
        null // Handle invalid Base64 string
    }
}

@Composable
fun Base64Image(base64String: String, contentDescription: String?) {
    // Decode and remember the bitmap
    val bitmap = remember(base64String) {
        decodeBase64ToBitmap(base64String)
    }

    if (bitmap != null) {
        Image(
            modifier = Modifier.fillMaxWidth(),
            bitmap = bitmap.asImageBitmap(),
            contentDescription = contentDescription,
            contentScale = ContentScale.Crop  // Material 3 scaling
        )
    } else {
        // Fallback if decoding fails
        Text("Failed to load image")
    }
}